validator:
function validate(input) {
  const [{ Points = [] }] = input;
  const seen = new Set();
  for (const [id, x, y] of Points) {
    if (id === null) return 'Every point needs an id.';
    if (seen.has(id)) return `id ${id} appears twice in Points.`;
    seen.add(id);
    if (x === null || y === null) return `Point ${id} needs both coordinates.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 110;
  const coords = small ? [-1, 0, 2, 4, 5, 7] : null;
  const pick = () => (coords ? coords[Math.floor(rand() * coords.length)] : Math.floor(rand() * 41) - 10);
  const ids = [];
  for (let i = 1; i <= count; i++) ids.push(i * 3 - 1);
  // Shuffle so ids are stored out of order.
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Points = ids.map((id) => [id, pick(), pick()]);
  return [{ Points }];
}
